import sys

MOD = 998244353

def create_pascal_triangle(size):
    pascal = [[0] * (size + 1) for _ in range(size + 1)]
    for i in range(size + 1):
        pascal[i][0] = 1
        for j in range(1, i + 1):
            pascal[i][j] = (pascal[i - 1][j - 1] + pascal[i - 1][j]) % MOD
    return pascal

def fast_power(base, exp):
    res = 1
    b = base
    e = exp
    while e > 0:
        if e & 1:
            res = (res * b) % MOD
        b = (b * b) % MOD
        e >>= 1
    return res

def main():
    input_str = sys.stdin.read().strip().split()
    n, k, l = map(int, input_str)
    pascal = create_pascal_triangle(n)
    p = [0] * (2 * n + 1)
    q = [0] * (2 * n + 1)
    a = [0] * (2 * n + 1)

    p[n] = fast_power(2, n)
    for _ in range(n):
        for j in range(2 * n, 0, -1):
            p[j] = (p[j] - p[j - 1]) % MOD

    for j in range(2 * n + 1):
        a[j] = p[j]

    inv2 = (MOD + 1) // 2
    for i in range(1, n - k + 1):
        for j in range(0, 2 * n):
            q[j] = (p[j + 1] * inv2) % MOD
        q[2 * n] = 0
        for j in range(1, 2 * n + 1):
            q[j] = (q[j] + q[j - 1]) % MOD
        for j in range(0, 2 * n + 1):
            p[j] = (q[j] - p[j]) % MOD
        c = pascal[n][i]
        for j in range(2 * n + 1):
            a[j] = (a[j] + c * p[j]) % MOD

    total = 0
    inv = fast_power(n + 1, MOD - 2)
    for i in range(2 * n + 1):
        total = (total + a[i] * fast_power(i + 1, MOD - 2)) % MOD
    total = (total * l) % MOD
    print(total)

if __name__ == "__main__":
    main()

